from typing import List, Tuple

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(2)]
    dp[0][0][0] = grid[0][0]

    for i in range(2):
        for x1 in range(N):
            for y1 in range(N):
                for x2 in range(N):
                    y2 = x1 + y1 - x2
                    if y2 < 0 or y2 >= N:
                        continue
                    if grid[x1][y1] == -1 or grid[x2][y2] == -1:
                        continue
                    if i == 0:
                        dp[i][x1][y1] = max(dp[i][x1][y1], dp[i][x1-1][y1] + grid[x1][y1] if x1 > 0 else grid[x1][y1])
                        if x1 != y1:
                            dp[i][x1][y1] = max(dp[i][x1][y1], dp[i][x1][y1-1] + grid[x1][y1] if y1 > 0 else grid[x1][y1])
                    else:
                        dp[i][x1][y1] = max(dp[i][x1][y1], dp[i-1][x2-1][y2-1] + grid[x1][y1] + grid[x2][y2] if x1 > 0 and y1 > 0 and x2 > 0 and y2 > 0 else 0)
                        dp[i][x1][y1] = max(dp[i][x1][y1], dp[i-1][x2][y2-1] + grid[x1][y1] + grid[x2][y2] if y1 > 0 and y2 > 0 else 0)
                        dp[i][x1][y1] = max(dp[i][x1][y1], dp[i-1][x2-1][y2] + grid[x1][y1] + grid[x2][y2] if x1 > 0 and x2 > 0 else 0)
                        if x1 != y1:
                            dp[i][x1][y1] = max(dp[i][x1][y1], dp[i-1][x2][y2] + grid[x1][y1] + grid[x2][y2] if y2 > 0 else 0)

    return max(max(max(row) for row in grid) + max(max(row) for row in dp[i-1]) for i in range(2))
