from typing import List, Tuple

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Create a grid to store values
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize DP tables
    dp = [[[0, 0] for _ in range(N)] for _ in range(N)]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                dp[i][j][0] = grid[i][j]
                dp[i][j][1] = 0
            else:
                dp[i][j][0] = grid[i][j] + max(dp[max(0, i-1)][j][1], dp[i][max(0, j-1)][1])
                dp[i][j][1] = grid[i][j] + max(dp[max(0, i-1)][max(0, j-1)][0], dp[max(0, i-1)][j][0], dp[i][max(0, j-1)][0])

    # The answer is the maximum value collected by either path
    return max(dp[N-1][N-1][0], dp[N-1][N-1][1])
