def cantor_numbering(N: int) -> str:
    if N <= 0:
        return "0/1"

    line = 1
    while N > line:
        N -= line
        line += 1

    if line % 2 == 0:
        numerator = 1 + (line * (line - 1)) // 2 - N + 1
        denominator = line - numerator + 1
    else:
        numerator = N
        denominator = line - N + 1

    return f"{numerator}/{denominator}"
