def cantor_numbering(N: int) -> str:
    line = 1
    count = 1

    while count < N:
        line += 1
        count += line

    if line % 2 == 0:
        numerator = N - (count - line)
        denominator = line - numerator + 1
    else:
        numerator = line - (count - N)
        denominator = N - numerator + 1

    return f"{numerator}/{denominator}"

