def max_product(num_str: str, N: int, K: int) -> int:
    from functools import lru_cache
    @lru_cache(None)
    def dp(i, k):
        if k < 0:
            return 0
        if i == N:
            return 1
        max_val = 0
        for j in range(i, N):
            product = int(num_str[i:j+1])
            max_val = max(max_val, product * dp(j+1, k-1))
        return max_val
    return dp(0, K)
