def max_product(num_str: str, N: int, K: int) -> int:
    max_product = 0
    for i in range(1, N):
        first_part = int(num_str[:i])
        second_part = int(num_str[i:])
        current_product = first_part * second_part
        if K > 0:
            current_product *= max_product(num_str[i:], N - i, K - 1)
        if current_product > max_product:
            max_product = current_product
    return max_product
