def max_product(num_str: str, N: int, K: int) -> int:
    if K == 0:
        return int(num_str)

    num_list = list(map(int, num_str))
    results = []

    def backtrack(start, current_product, current_expression):
        if start == N:
            results.append(current_product)
            return

        for i in range(start, N):
            if current_expression:
                backtrack(i + 1, current_product * num_list[i], current_expression + '*' + str(num_list[i]))
            else:
                backtrack(i + 1, num_list[i], str(num_list[i]))

    backtrack(1, num_list[0], str(num_list[0]))
    return max(results)

