def max_product(num_str: str, N: int, K: int) -> int:
    from functools import reduce
    from itertools import combinations

    def split_and_multiply(s, splits):
        parts = [s[start:end] for start, end in zip([0] + splits, splits + [len(s)])]
        return reduce(lambda x, y: x * int(y), parts)

    max_product = 0
    for splits in combinations(range(1, N), K):
        product = split_and_multiply(num_str, splits)
        max_product = max(max_product, product)

    return max_product
```

