def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        total = 0
        for i, digit in enumerate(isbn):
            if digit.isnumeric():
                total += int(digit) * (10 - i)
            elif digit == 'X':
                total += 10 * (10 - i)
        return total % 11

    isbn_parts = isbn.split('-')
    if len(isbn_parts) != 5 or isbn_parts[4] not in '0123456789X':
        return "Invalid ISBN format"

    calculated_checksum = calculate_checksum(isbn_parts[0] + isbn_parts[1] + isbn_parts[2] + isbn_parts[3])
    expected_checksum = int(isbn_parts[4]) if isbn_parts[4].isnumeric() else 10

    if calculated_checksum == expected_checksum:
        return "Right"
    else:
        corrected_parts = list(isbn_parts)
        corrected_parts[4] = str(10 - calculated_checksum) if calculated_checksum != 10 else 'X'
        return '-'.join(corrected_parts)
