def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    # Initialize counters for separating pairs horizontally and vertically
    horizontal_separation = [0] * (M + 1)
    vertical_separation = [0] * (N + 1)

    # Count how many pairs can be separated by adding an aisle at each possible row and column
    for (Xi, Yi, Pi, Qi) in chatting_pairs:
        if Xi == Pi:
            # Chatting horizontally, add to vertical separation count for columns between Xi and Qi
            start, end = sorted([Yi, Qi])
            for col in range(start, end):
                vertical_separation[col] += 1
        else:
            # Chatting vertically, add to horizontal separation count for rows between Xi and Pi
            start, end = sorted([Xi, Pi])
            for row in range(start, end):
                horizontal_separation[row] += 1

    # Find the K positions with the most horizontal separations
    horizontal_aisles = [str(i) for i, count in enumerate(horizontal_separation[1:], start=1) if count == max(horizontal_separation[1:])]
    if len(horizontal_aisles) > K:
        horizontal_aisles = horizontal_aisles[:K]

    # Find the L positions with the most vertical separations
    vertical_aisles = [str(i) for i, count in enumerate(vertical_separation[1:], start=1) if count == max(vertical_separation[1:])]
    if len(vertical_aisles) > L:
        vertical_aisles = vertical_aisles[:L]

    # Return the optimal row and column indices for the aisles
    row_aisles = ' '.join(horizontal_aisles) if horizontal_aisles else '-1'
    col_aisles = ' '.join(vertical_aisles) if vertical_aisles else '-1'

    return (row_aisles, col_aisles)

