def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    def separate_pairs_with_aisle(aisle_positions, pairs):
        count = 0
        for a, b in pairs:
            if not (aisle_positions[0] <= a <= aisle_positions[1] or aisle_positions[0] <= b <= aisle_positions[1]):
                count += 1
        return count

    row_separations = []
    col_separations = []

    for i in range(1, M):
        row_separations.append(separate_pairs_with_aisle((i, i), chatting_pairs))

    for j in range(1, N):
        col_separations.append(separate_pairs_with_aisle((j, j), chatting_pairs))

    row_aisle_positions = sorted(range(1, M), key=lambda x: row_separations[x-1], reverse=True)[:K]
    col_aisle_positions = sorted(range(1, N), key=lambda x: col_separations[x-1], reverse=True)[:L]

    return (' '.join(map(str, row_aisle_positions)), ' '.join(map(str, col_aisle_positions)))
