def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7

    def comb(n, k):
        if k > n:
            return 0
        num = den = 1
        for i in range(k):
            num = num * (n - i) % MOD
            den = den * (i + 1) % MOD
        return num * pow(den, MOD - 2, MOD) % MOD

    dp = [0] * (m + 1)
    dp[0] = 1

    for i in range(n):
        for j in range(m, a[i] - 1, -1):
            dp[j] = (dp[j] + dp[j - a[i]]) % MOD

    return dp[m]
