def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Find the peak position
    peak = 0
    for i in range(1, n):
        if heights[i] > heights[peak]:
            peak = i

    # Calculate the number of students to leave for the increasing part
    left = 0
    for i in range(peak):
        if heights[i] > heights[i - 1]:
            left += 1
        else:
            break

    # Calculate the number of students to leave for the decreasing part
    right = 0
    for i in range(peak, n - 1):
        if heights[i] > heights[i + 1]:
            right += 1
        else:
            break

    # Calculate the minimum number of students to leave
    return left + right - (1 if heights[peak] == heights[peak - 1] and peak > 0 else 0)
