def hanoi_double_iterative(n: int) -> int:
    if n <= 0:
        return 0
    moves = [0] * (n + 1)
    moves[1] = 2
    for i in range(2, n + 1):
        moves[i] = 2 * moves[i - 1] + 2
    return moves[n]

